        _notify(key, type) {
            try {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t(key), type || 'info');
            } catch (e) { /* preview / headless */ }
        }

        _t(key) {
            try { return window.mySimulation.t(key); } catch (e) { return key; }
        }

        _syncUI(state) {
            this._updateBriefing(state);
            this._buildDecisionPanel(state);
            this._renderEventCard(state);
        }

        _updateBriefing(state) {
            var period = Math.min(Math.max(state.currentPeriod || 1, 1), 4);
            var keys = ['brief_q1', 'brief_q2', 'brief_q3', 'brief_q4'];
            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = this._t(keys[period - 1]);
        }

        _renderEventCard(state) {
            var card = document.getElementById('eventCard');
            if (!card) return;
            var ds = state.domainState || {};
            var title = document.getElementById('eventCardTitle');
            var body = document.getElementById('eventCardBody');
            if (ds.crisisId && ds.crisisPeriod && (state.currentPeriod || 1) > ds.crisisPeriod) {
                if (title) title.textContent = this._t('crisis_title') + ' — Q' + ds.crisisPeriod;
                if (body) body.innerHTML = this._t('hint_crisis_' + ds.crisisId);
                card.style.display = '';
                card.hidden = false;
            } else {
                card.style.display = 'none';
                card.hidden = true;
            }
        }

        _renderCapital(state, round, total) {
            var ds = state.domainState || {};
            var remaining = (ds.capitalAvailable || 0) - (ds.capitalSpent || 0);
            var el = document.getElementById('capitalRemaining');
            if (el) {
                el.textContent = this._t('capital_remaining') + ' $' + Math.max(0, remaining).toFixed(1) + 'M / $'
                    + (ds.capitalAvailable || 0).toFixed(0) + 'M';
            }
            var err = document.getElementById('budgetError');
            var submitBtn = document.getElementById('nextPeriodBtn');
            var over = null;
            if (total > round.maxBudget + 1e-9) over = 'budget_exceeded';
            else if (total > remaining + 1e-9) over = 'capital_exceeded';
            if (err) {
                if (over) { err.textContent = this._t(over); err.hidden = false; err.style.display = ''; }
                else { err.textContent = ''; err.hidden = true; err.style.display = 'none'; }
            }
            if (submitBtn) {
                submitBtn.disabled = !!over;
                if (over) submitBtn.setAttribute('aria-disabled', 'true');
                else submitBtn.removeAttribute('aria-disabled');
            }
        }

        _buildDecisionPanel(state) {
            var period = Math.min(Math.max(state.currentPeriod || 1, 1), 4);
            var roundIdx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];
            var panel = document.getElementById('decisionPanel');
            if (!panel) return;

            var self = this;
            var html = '';

            for (var i = 0; i < round.investments.length; i++) {
                var inv = round.investments[i];
                var descId = 'invdesc_' + inv.id;
                html += '<div class="circular-sim-inv-option">';
                html += '<input type="checkbox" class="circular-sim-inv-check" data-inv-id="' + inv.id + '" data-inv-cost="' + inv.cost + '" id="inv_' + inv.id + '" aria-describedby="' + descId + '">';
                html += '<label for="inv_' + inv.id + '">' + this._t('inv_' + inv.id) + '</label>';
                html += '<span class="circular-sim-inv-cost">$' + inv.cost.toFixed(1) + 'M</span>';
                html += '</div>';
                html += '<div class="circular-sim-inv-desc" id="' + descId + '">' + this._t('inv_' + inv.id + '_desc') + '</div>';
            }

            if (round.hasSpecialDecision && round.specialType === 'telcomax') {
                html += '<div class="circular-sim-radio-group" role="radiogroup" aria-labelledby="telcomaxTitle">';
                html += '<h4 id="telcomaxTitle">' + this._t('telcomax_title') + '</h4>';
                html += '<p>' + this._t('telcomax_desc') + '</p>';
                html += '<div class="circular-sim-radio-option"><label><input type="radio" name="telcomaxBid" value="accept"> ' + this._t('telcomax_accept') + '</label></div>';
                html += '<div class="circular-sim-radio-option"><label><input type="radio" name="telcomaxBid" value="decline" checked> ' + this._t('telcomax_decline') + '</label></div>';
                html += '</div>';
            }

            if (round.hasSpecialDecision && round.specialType === 'organizational') {
                html += '<div class="circular-sim-radio-group" role="radiogroup" aria-labelledby="orgTitle">';
                html += '<h4 id="orgTitle">' + this._t('org_title') + '</h4>';
                html += '<p>' + this._t('org_desc') + '</p>';
                html += '<div class="circular-sim-radio-option"><label><input type="radio" name="orgResponse" value="restructure"> ' + this._t('org_restructure') + '</label><div class="circular-sim-inv-desc">' + this._t('org_restructure_desc') + '</div></div>';
                html += '<div class="circular-sim-radio-option"><label><input type="radio" name="orgResponse" value="engage" checked> ' + this._t('org_engage') + '</label><div class="circular-sim-inv-desc">' + this._t('org_engage_desc') + '</div></div>';
                html += '<div class="circular-sim-radio-option"><label><input type="radio" name="orgResponse" value="defer"> ' + this._t('org_defer') + '</label><div class="circular-sim-inv-desc">' + this._t('org_defer_desc') + '</div></div>';
                html += '</div>';
            }

            if (round.hasSpecialDecision && round.specialType === 'boardDefense') {
                html += '<div class="circular-sim-radio-group" role="radiogroup" aria-labelledby="boardTitle">';
                html += '<h4 id="boardTitle">' + this._t('board_title') + '</h4>';
                html += '<p>' + this._t('board_desc') + '</p>';
                html += '<div class="circular-sim-radio-option"><label><input type="radio" name="boardNarrative" value="forward"> ' + this._t('board_forward') + '</label></div>';
                html += '<div class="circular-sim-radio-option"><label><input type="radio" name="boardNarrative" value="transparent" checked> ' + this._t('board_transparent') + '</label></div>';
                html += '<div class="circular-sim-radio-option"><label><input type="radio" name="boardNarrative" value="defensive"> ' + this._t('board_defensive') + '</label></div>';
                html += '</div>';
            }

            panel.innerHTML = html;

            var budgetDisplay = document.getElementById('budgetDisplay');
            var budgetFill = document.getElementById('budgetFill');

            function recalc() {
                var total = 0;
                var selected = panel.querySelectorAll('.circular-sim-inv-check:checked');
                for (var s = 0; s < selected.length; s++) {
                    total += parseFloat(selected[s].getAttribute('data-inv-cost'));
                }
                var telco = document.querySelector('input[name="telcomaxBid"]:checked');
                var committed = total + (telco && telco.value === 'accept' ? self.TELCOMAX_COST : 0);

                if (budgetDisplay) budgetDisplay.textContent = '$' + total.toFixed(1) + 'M / $' + round.maxBudget.toFixed(0) + 'M';
                if (budgetFill) {
                    budgetFill.style.width = Math.min(100, (total / round.maxBudget) * 100) + '%';
                    budgetFill.style.background = (total > round.maxBudget)
                        ? 'linear-gradient(90deg, #f44336, #e53935)'
                        : 'linear-gradient(90deg, #00897b, #4caf50)';
                }
                self._renderCapital(state, round, committed);
            }

            var checks = panel.querySelectorAll('.circular-sim-inv-check');
            for (var c = 0; c < checks.length; c++) {
                checks[c].addEventListener('change', recalc);
            }
            var radios = panel.querySelectorAll('input[type="radio"]');
            for (var rr = 0; rr < radios.length; rr++) {
                radios[rr].addEventListener('change', recalc);
            }

            if (budgetDisplay) budgetDisplay.textContent = '$0.0M / $' + round.maxBudget.toFixed(0) + 'M';
            if (budgetFill) budgetFill.style.width = '0%';
            this._renderCapital(state, round, 0);
        }

